#include <iostream>
#include <memory>
#include <vector>
#include <iomanip>

class Employee {
public:
    virtual ~Employee() = default;
    virtual void print() const = 0;
    virtual double earnings() const = 0;
};

class SalariedEmployee : public Employee {
private:
    double weeklySalary;
public:
    explicit SalariedEmployee(double salary) : weeklySalary(salary) {}
    void print() const override {
        std::cout << "salaried employee, salary: " << weeklySalary;
    }
    double earnings() const override {
        return weeklySalary;
    }
};

class CommissionEmployee : public Employee {
private:
    double grossSales;
    double commissionRate;
public:
    CommissionEmployee(double sales, double rate) 
        : grossSales(sales), commissionRate(rate) {}
    void print() const override {
        std::cout << "commission employee, sales: " << grossSales 
                  << ", rate: " << commissionRate;
    }
    double earnings() const override {
        return grossSales * commissionRate;
    }
};

void callViaPointer(const Employee* ptr) {
    if (ptr) {
        ptr->print();
        std::cout << " | earned: $" << ptr->earnings() << "\n";
    }
}

void callViaReference(const Employee& ref) {
    ref.print();
    std::cout << " | earned: $" << ref.earnings() << "\n";
}

int main() {
    std::cout << std::fixed << std::setprecision(2);

    std::vector<std::unique_ptr<Employee>> employees;
    employees.push_back(std::make_unique<SalariedEmployee>(800.00));
    employees.push_back(std::make_unique<CommissionEmployee>(10000.00, 0.06));

    std::cout << "Virtual calls via pointers:\n";
    for (const auto& emp : employees) {
        callViaPointer(emp.get());
    }

    std::cout << "\nVirtual calls via references:\n";
    for (const auto& emp : employees) {
        callViaReference(*emp);
    }

    return 0;
}

#include <iostream>

// Non-polymorphic class (no virtual functions)
class NonVirtualClass {
    int data{42};
public:
    void show() const {
        std::cout << "NonVirtual: " << data << "\n";
    }
};

// Polymorphic class (introduces virtual table pointer - vptr)
class VirtualClass {
    int data{42};
public:
    virtual ~VirtualClass() = default;
    virtual void show() const {
        std::cout << "VirtualClass: " << data << "\n";
    }
};

// Derived class inheriting vtable mechanism
class DerivedClass : public VirtualClass {
    int extraData{100};
public:
    void show() const override {
        std::cout << "DerivedClass show() override\n";
    }
};

int main() {
    std::cout << "Size of int: " << sizeof(int) << " bytes\n";
    std::cout << "Size of pointer: " << sizeof(void*) << " bytes\n";

    // Non-polymorphic object size contains only member data (+ padding if needed)
    std::cout << "Size of NonVirtualClass: " << sizeof(NonVirtualClass) << " bytes\n";

    // Polymorphic object size includes vptr (pointer to vtable) + data members
    std::cout << "Size of VirtualClass: " << sizeof(VirtualClass) << " bytes\n";
    std::cout << "Size of DerivedClass: " << sizeof(DerivedClass) << " bytes\n";

    DerivedClass d;
    VirtualClass* basePtr = &d;

    // Dynamic dispatch resolving through vtable at runtime
    basePtr->show();

    return 0;
}
